  284: /**
  285:  * @brief Handles reward selection when turning in a quest.
  286:  *
  287:  * @param recv_data The received opcode packet.
  288:  */
  289: void QuestHandlers::HandleQuestgiverChooseReward(WorldSession& session, WorldPacket& recv_data)
  290: {
  291:     uint32 quest, reward;
  292:     ObjectGuid guid;
  293:     recv_data >> guid >> quest >> reward;
  294: 
  295:     if (reward >= QUEST_REWARD_CHOICES_COUNT)
  296:     {
  297:         sLog.outError("Error in CMSG_QUESTGIVER_CHOOSE_REWARD - %s tried to get invalid reward (%u) (probably packet hacking)", session.GetPlayer()->GetGuidStr().c_str(), reward);
  298:         return;
  299:     }
  300: 
  301:     if (!CanInteractWithQuestGiver(session, guid, "CMSG_QUESTGIVER_CHOOSE_REWARD"))
  302:     {
  303:         return;
  304:     }
  305: 
  306:     DEBUG_LOG("WORLD: Received opcode CMSG_QUESTGIVER_CHOOSE_REWARD - for %s to %s, quest = %u, reward = %u", session.GetPlayer()->GetGuidStr().c_str(), guid.GetString().c_str(), quest, reward);
  307: 
  308:     Object* pObject = session.GetPlayer()->GetObjectByTypeMask(guid, TYPEMASK_CREATURE_OR_GAMEOBJECT);
  309:     if (!pObject)
  310:     {
  311:         return;
  312:     }
  313: 
  314:     if (!pObject->HasInvolvedQuest(quest))
  315:     {
  316:         return;
  317:     }
  318: 
  319:     Quest const* pQuest = sObjectMgr.GetQuestTemplate(quest);
  320:     if (pQuest)
  321:     {
  322:         if (session.GetPlayer()->CanRewardQuest(pQuest, reward, true))
  323:         {
  324:             // Decided before the reward so the packet's UseQuestReward bit and the follow-up below agree:
  325:             // the client keeps QuestFrame open only when the next quest's details really follow.
  326:             Quest const* nextquest = session.GetPlayer()->GetNextQuest(guid, pQuest);
  327:             session.GetPlayer()->RewardQuest(pQuest, reward, pObject, true, nextquest != NULL);
  328: 
  329:             // Send next quest
  330:             if (nextquest)
  331:             {
  332:                 session.GetPlayer()->PlayerTalkClass->SendQuestGiverQuestDetails(nextquest, guid, true);
  333:             }
  334:             else if (pObject->GetTypeId() == TYPEID_UNIT)
  335:             {
  336:                 Creature* pCreature = (Creature*)pObject;
  337:                 session.GetPlayer()->PrepareGossipMenu(pCreature, pCreature->GetCreatureInfo()->GossipMenuId);
  338: 
  339:                 if (!session.GetPlayer()->PlayerTalkClass->Empty())
  340:                 {
  341:                     session.GetPlayer()->SendPreparedGossip(pCreature);
  342:                 }
  343:             }
  344:             else
  345:             {
  346:                 session.GetPlayer()->PrepareQuestMenu(guid);
  347:                 session.GetPlayer()->SendPreparedQuest(guid);
  348:             }
  349:         }
  350:         else
  351:         {
  352:             session.GetPlayer()->PlayerTalkClass->SendQuestGiverOfferReward(pQuest, guid, true);
  353:         }
  354:     }
  355: }
