  397: /**
  398:  * @brief Removes a quest from the player's quest log.
  399:  *
  400:  * @param recv_data The received opcode packet.
  401:  */
  402: void QuestHandlers::HandleQuestLogRemoveQuest(WorldSession& session, WorldPacket& recv_data)
  403: {
  404:     uint8 slot;
  405:     recv_data >> slot;
  406: 
  407:     DEBUG_LOG("WORLD: Received opcode CMSG_QUESTLOG_REMOVE_QUEST slot = %u", slot);
  408: 
  409:     if (slot < MAX_QUEST_LOG_SIZE)
  410:     {
  411:         if (uint32 quest = session.GetPlayer()->GetQuestSlotQuestId(slot))
  412:         {
  413:             if (!session.GetPlayer()->TakeQuestSourceItem(quest, true))
  414:             {
  415:                 return;                                     // can't un-equip some items, reject quest cancel
  416:             }
  417: 
  418:             if (const Quest* pQuest = sObjectMgr.GetQuestTemplate(quest))
  419:             {
  420:                 if (pQuest->HasSpecialFlag(QUEST_SPECIAL_FLAG_TIMED))
  421:                 {
  422:                     session.GetPlayer()->GetQuestStatusMgr().RemoveTimedQuest(quest);
  423:                 }
  424: 
  425:                 for (int i = 0; i < QUEST_SOURCE_ITEM_IDS_COUNT; ++i)
  426:                 {
  427:                     if (pQuest->ReqSourceId[i])
  428:                     {
  429:                         ItemPrototype const* iProto = ObjectMgr::GetItemPrototype(pQuest->ReqSourceId[i]);
  430:                         if (iProto && iProto->Bonding == BIND_QUEST_ITEM)
  431:                         {
  432:                             session.GetPlayer()->DestroyItemCount(pQuest->ReqSourceId[i], pQuest->ReqSourceCount[i], true, false, true);
  433:                         }
  434:                     }
  435:                 }
  436:             }
  437: 
  438:             session.GetPlayer()->SetQuestStatus(quest, QUEST_STATUS_NONE);
  439: 
  440:             if (sGameConfig.getConfig(CONFIG_BOOL_ENABLE_QUEST_TRACKER)) // check if Quest Tracker is enabled
  441:             {
  442:                 DEBUG_LOG("QUEST TRACKER: Quest Abandoned.");
  443:                 QuestTrackerRepository::SetAbandonTime(quest, session.GetPlayer()->GetGUIDLow());
  444:             }
  445:         }
  446: 
  447:         session.GetPlayer()->SetQuestSlot(slot, 0);
  448: 
  449:         session.GetPlayer()->GetAchievementMgr().UpdateAchievementCriteria(ACHIEVEMENT_CRITERIA_TYPE_QUEST_ABANDONED, 1);
  450:     }
  451: }
