  503: /**
  504:  * @brief Begins quest completion processing with a quest giver.
  505:  *
  506:  * @param recv_data The received opcode packet.
  507:  */
  508: void QuestHandlers::HandleQuestgiverCompleteQuest(WorldSession& session, WorldPacket& recv_data)
  509: {
  510:     uint32 quest;
  511:     ObjectGuid guid;
  512:     uint8 unk;
  513:     recv_data >> guid >> quest >> unk;
  514: 
  515:     if (!CanInteractWithQuestGiver(session, guid, "CMSG_QUESTGIVER_COMPLETE_QUEST"))
  516:     {
  517:         return;
  518:     }
  519: 
  520:     // All ok, continue
  521:     DEBUG_LOG("WORLD: Received opcode CMSG_QUESTGIVER_COMPLETE_QUEST - for %s to %s, quest = %u, unk = %u", session.GetPlayer()->GetGuidStr().c_str(), guid.GetString().c_str(), quest, unk);
  522: 
  523:     if (Quest const* pQuest = sObjectMgr.GetQuestTemplate(quest))
  524:     {
  525:         if (session.GetPlayer()->GetQuestStatusMgr().GetQuestStatus(quest) != QUEST_STATUS_COMPLETE)
  526:         {
  527:             if (pQuest->IsRepeatable())
  528:             {
  529:                 session.GetPlayer()->PlayerTalkClass->SendQuestGiverRequestItems(pQuest, guid, session.GetPlayer()->CanCompleteRepeatableQuest(pQuest), false);
  530:             }
  531:             else
  532:             {
  533:                 session.GetPlayer()->PlayerTalkClass->SendQuestGiverRequestItems(pQuest, guid, session.GetPlayer()->CanRewardQuest(pQuest, false), false);
  534:             }
  535:         }
  536:         else
  537:         {
  538:             if (pQuest->GetReqItemsCount() || pQuest->GetReqCurrencyCount())    // some items or currency required
  539:             {
